from logging.config import fileConfig

from alembic import context
from sqlalchemy import engine_from_config, pool
from sqlalchemy.schema import Column, SchemaItem

from opsmesh.bootstrap.models import register_models
from opsmesh.shared.config import get_settings

config = context.config

if config.config_file_name is not None:
    fileConfig(config.config_file_name, disable_existing_loggers=False)

target_metadata = register_models()

# These exact objects preserve historical facts for downgrade and have no ORM consumers.
# Keep them out of autogenerated removals; all other schema differences remain visible.
MIGRATION_ONLY_TABLES = frozenset(
    {
        "execution_contract_rollback",  # 0116
        "retired_model_fallback_settings",  # 0137
        "retired_agent_provider_configuration",  # 0142
        "archived_plugin_deployments",  # 0147
    }
)


def include_object(
    object_: SchemaItem,
    name: str | None,
    type_: str,
    reflected: bool,
    compare_to: SchemaItem | None,
) -> bool:
    """Protect explicit migration archives without suppressing ordinary schema drift."""
    if reflected and compare_to is None:
        if type_ == "table" and name in MIGRATION_ONLY_TABLES:
            return False
        if (
            type_ == "column"
            and isinstance(object_, Column)
            and object_.table.name == "workspaces"
            and name == "legacy_approval_settings"  # 0112 downgrade archive
        ):
            return False
    return True


def get_database_url() -> str:
    configured_url = config.get_main_option("sqlalchemy.url")
    if configured_url:
        return configured_url
    return get_settings().database_url


def run_migrations_offline() -> None:
    context.configure(
        url=get_database_url(),
        target_metadata=target_metadata,
        literal_binds=True,
        dialect_opts={"paramstyle": "named"},
        include_object=include_object,
    )

    with context.begin_transaction():
        context.run_migrations()


def run_migrations_online() -> None:
    configuration = config.get_section(config.config_ini_section, {})
    configuration["sqlalchemy.url"] = get_database_url()
    connectable = engine_from_config(
        configuration,
        prefix="sqlalchemy.",
        poolclass=pool.NullPool,
    )

    with connectable.connect() as connection:
        context.configure(
            connection=connection, target_metadata=target_metadata, include_object=include_object
        )

        with context.begin_transaction():
            context.run_migrations()


if context.is_offline_mode():
    run_migrations_offline()
else:
    run_migrations_online()
